package com.example.webapptemplate.janken;
import com.example.webapptemplate.ai.AiDraftResult;import com.example.webapptemplate.authors.AuthorOperations;import java.util.*;import jakarta.servlet.http.HttpSession;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;import org.springframework.http.ResponseEntity;
@Controller public class JankenController {
 private final JankenService service;private final AuthorOperations users;public JankenController(JankenService service,AuthorOperations users){this.service=service;this.users=users;}
 @GetMapping("/janken") public String show(@RequestParam(required=false)UUID user,Model model){var choices=users.choices();if(model.getAttribute("currentAuthor") instanceof com.example.webapptemplate.authors.AuthorView selected)user=selected.id();if(user!=null)users.requireAuthor(user);model.addAttribute("players",choices);model.addAttribute("player",user);model.addAttribute("history",service.history(user));model.addAttribute("total",service.total(user));return "janken/play";}
 @PostMapping("/janken/round") @ResponseBody public Object play(@RequestParam UUID requestId,@RequestParam UUID user,@RequestParam String character,@RequestParam String hand,@RequestParam String skill){return service.play(requestId,user,character,hand,skill);}
 @PostMapping("/janken/line/draft") @ResponseBody public Object draft(@RequestParam UUID requestId,@RequestParam String character,@RequestParam String material,HttpSession session){synchronized(session){var old=(AiDraftResult)session.getAttribute("jankenDraft");if(old!=null&&old.requestId().equals(requestId))return old;var result=service.draft(requestId,character,material);session.setAttribute("jankenDraft",result);return result;}}
 @PostMapping("/janken/line") @ResponseBody public Object adopt(@RequestParam UUID user,@RequestParam String character,@RequestParam String line){service.adopt(user,character,line);return Map.of("message","確認したセリフを保存しました。次の対戦で使います。");}
 @ExceptionHandler(IllegalArgumentException.class) @ResponseBody public ResponseEntity<?> invalid(IllegalArgumentException e){return ResponseEntity.badRequest().body(Map.of("error",e.getMessage()));}
 @ExceptionHandler(org.springframework.dao.DataAccessException.class) @ResponseBody public ResponseEntity<?> unavailable(){return ResponseEntity.status(503).body(Map.of("error","保存を確認できませんでした。同じ操作を再試行できます。"));}
}
